export interface BlacklistEntry {
  nationalId: string;
  fullName: string;
  passportNumber: string;
  department: string;
  dateOfHire: string;
  dateOfTermination: string;
  reasonForBlacklisting: string;
  specificNotes: string;
  status: 'Blacklisted' | 'Pending Review' | 'Cleared';
  timestamp: string;
}

export interface WebhookResponse {
  success: boolean;
  message: string;
}

export type ViewState = 'dashboard' | 'entry' | 'search';

import { BlacklistEntry, WebhookResponse } from '../types';

const WEBHOOK_URL = 'https://tmoose.app.n8n.cloud/webhook/2c324a11-fa86-4518-8941-a880e8259f6c';

export const submitToBlacklist = async (data: BlacklistEntry): Promise<WebhookResponse> => {
  try {
    const response = await fetch(WEBHOOK_URL, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(data),
    });

    if (response.ok) {
      return { success: true, message: 'Entry logged successfully to central database.' };
    } else {
      return { success: false, message: `Server error: ${response.statusText}` };
    }
  } catch (error) {
    console.error("Webhook submission failed", error);
    return { success: false, message: 'Network error: Could not reach the server.' };
  }
};

import { GoogleGenAI, Type } from "@google/genai";
import { BlacklistEntry } from "../types";

// Helper to convert file to base64
export const fileToGenerativePart = async (file: File): Promise<{ inlineData: { data: string; mimeType: string } }> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onloadend = () => {
      const base64String = reader.result as string;
      // Remove data url prefix (e.g. "data:image/jpeg;base64,")
      const base64Data = base64String.split(',')[1];
      resolve({
        inlineData: {
          data: base64Data,
          mimeType: file.type,
        },
      });
    };
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
};

export const analyzeDocuments = async (files: File[]): Promise<Partial<BlacklistEntry>> => {
  if (!process.env.API_KEY) {
    throw new Error("API Key is missing.");
  }

  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const fileParts = await Promise.all(files.map(fileToGenerativePart));

  const prompt = `
    You are an expert HR document analyzer for "Faiz -e- Husaini".

    Analyze the attached images. These may include:
    1. An Iraqi National ID Card (contains a 12-digit unique ID).
    2. A Job Application form.
    3. Handwritten sticky notes or text on the documents indicating "Terminated", "Blacklisted", reasons (theft, etc.), and specific notes.

    Extract the following information accurately:
    - National ID Number (Crucial: 12 digits from the ID card).
    - Full Name (From ID or Application).
    - Passport Number (If available).
    - Department (From application).
    - Date of Hire (From application).
    - Date of Termination (From notes or application).
    - Reason for Blacklisting (Look for handwriting like "Theft", "Fraud", "Terminated", etc.).
    - Specific Notes (Any other details regarding the termination).
    - Status (Defaults to "Blacklisted").

    If a field is missing, leave it as an empty string. Return JSON only.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview', // Requested model
      contents: {
        role: 'user',
        parts: [
          ...fileParts,
          { text: prompt }
        ]
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            nationalId: { type: Type.STRING, description: "12 digit Iraqi National ID" },
            fullName: { type: Type.STRING },
            passportNumber: { type: Type.STRING },
            department: { type: Type.STRING },
            dateOfHire: { type: Type.STRING, description: "YYYY-MM-DD format if possible" },
            dateOfTermination: { type: Type.STRING, description: "YYYY-MM-DD format if possible" },
            reasonForBlacklisting: { type: Type.STRING },
            specificNotes: { type: Type.STRING },
            status: { type: Type.STRING, enum: ["Blacklisted", "Pending Review"] },
          },
          required: ["nationalId", "fullName", "reasonForBlacklisting"]
        }
      }
    });

    const text = response.text;
    if (!text) throw new Error("No response from AI");

    const data = JSON.parse(text);
    return data as Partial<BlacklistEntry>;

  } catch (error) {
    console.error("Gemini Analysis Error:", error);
    throw new Error("Failed to extract data from documents.");
  }
};

