import React, { useState, useEffect, useRef } from 'react';
import { 
  LayoutDashboard, 
  FilePlus, 
  Search, 
  ScanLine, 
  UploadCloud, 
  CheckCircle2, 
  AlertCircle,
  Loader2,
  Trash2,
  History,
  ShieldAlert
} from 'lucide-react';
import { BlacklistEntry, ViewState } from './types';
import { analyzeDocuments } from './services/geminiService';
import { submitToBlacklist } from './services/webhookService';
import { GlassCard } from './components/GlassCard';

// Constants
const CACHE_KEY = 'faiz_blacklist_cache';

const App: React.FC = () => {
  const [view, setView] = useState<ViewState>('dashboard');
  const [cache, setCache] = useState<BlacklistEntry[]>([]);

  // Form State
  const [files, setFiles] = useState<File[]>([]);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [formData, setFormData] = useState<Partial<BlacklistEntry>>({});
  const [showForm, setShowForm] = useState(false);
  const [notification, setNotification] = useState<{msg: string, type: 'success' | 'error'} | null>(null);

  // Search State
  const [searchQuery, setSearchQuery] = useState('');
  const [searchResult, setSearchResult] = useState<BlacklistEntry | null | undefined>(undefined);

  useEffect(() => {
    // Load cache on mount
    const saved = localStorage.getItem(CACHE_KEY);
    if (saved) {
      setCache(JSON.parse(saved));
    }
  }, []);

  const addToCache = (entry: BlacklistEntry) => {
    const newCache = [entry, ...cache].slice(0, 20); // Keep last 20
    setCache(newCache);
    localStorage.setItem(CACHE_KEY, JSON.stringify(newCache));
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      setFiles(Array.from(e.target.files));
    }
  };

  const processImages = async () => {
    if (files.length === 0) return;
    setIsAnalyzing(true);
    try {
      const result = await analyzeDocuments(files);
      setFormData({
        ...result,
        timestamp: new Date().toISOString(),
      });
      setShowForm(true);
    } catch (err) {
      setNotification({ msg: 'Failed to analyze documents. Please try again.', type: 'error' });
      setTimeout(() => setNotification(null), 4000);
    } finally {
      setIsAnalyzing(false);
    }
  };

  const handleSubmit = async () => {
    setIsSubmitting(true);
    // Ensure all required fields exist or have defaults
    const finalData: BlacklistEntry = {
      nationalId: formData.nationalId || 'UNKNOWN',
      fullName: formData.fullName || 'UNKNOWN',
      passportNumber: formData.passportNumber || '',
      department: formData.department || '',
      dateOfHire: formData.dateOfHire || '',
      dateOfTermination: formData.dateOfTermination || '',
      reasonForBlacklisting: formData.reasonForBlacklisting || 'Not Specified',
      specificNotes: formData.specificNotes || '',
      status: (formData.status as any) || 'Blacklisted',
      timestamp: new Date().toISOString(),
    };

    const result = await submitToBlacklist(finalData);

    if (result.success) {
      addToCache(finalData);
      setNotification({ msg: 'Successfully blacklisted and logged.', type: 'success' });
      // Reset
      setFiles([]);
      setShowForm(false);
      setFormData({});
      setView('dashboard');
    } else {
      setNotification({ msg: result.message, type: 'error' });
    }

    setIsSubmitting(false);
    setTimeout(() => setNotification(null), 4000);
  };

  const handleSearch = () => {
    if (!searchQuery) return;
    // Search local cache first (Simulating "Quick Check")
    // In a real full stack, this would fetch GET from the webhook/API
    const found = cache.find(
      c => c.nationalId.includes(searchQuery) || c.fullName.toLowerCase().includes(searchQuery.toLowerCase())
    );
    setSearchResult(found || null);
  };

  // --- Views ---

  const renderDashboard = () => (
    <div className="space-y-6 animate-in fade-in duration-500">
      <div className="flex justify-between items-end">
        <div>
          <h2 className="text-3xl font-thin text-white tracking-tight">Recent Activity</h2>
          <p className="text-white/50 mt-1 font-light">Last 20 Logged Entries</p>
        </div>
        <button 
          onClick={() => setView('entry')}
          className="bg-blue-600 hover:bg-blue-500 text-white px-6 py-2 rounded-full font-medium transition-all shadow-lg hover:shadow-blue-500/25 flex items-center gap-2"
        >
          <FilePlus size={18} /> New Entry
        </button>
      </div>

      <div className="grid gap-4">
        {cache.length === 0 ? (
          <GlassCard className="p-12 flex flex-col items-center justify-center text-white/30">
            <History size={48} className="mb-4" />
            <p>No recent blacklist logs found.</p>
          </GlassCard>
        ) : (
          cache.map((entry, idx) => (
            <GlassCard key={idx} className="p-6 flex items-center justify-between group hover:border-white/40">
              <div className="flex items-center gap-4">
                <div className="w-12 h-12 rounded-full bg-red-500/20 flex items-center justify-center text-red-400">
                  <ShieldAlert size={20} />
                </div>
                <div>
                  <h3 className="font-semibold text-lg">{entry.fullName}</h3>
                  <p className="text-white/50 text-sm font-mono">{entry.nationalId}</p>
