        </GlassCard>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <GlassCard className="p-6 md:col-span-2">
            <h3 className="text-xl font-medium mb-6 text-blue-300 flex items-center gap-2">
              <CheckCircle2 size={20} /> Extracted Data
            </h3>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div className="space-y-2">
                <label className="text-xs uppercase tracking-wider text-white/40">Full Name</label>
                <input 
                  value={formData.fullName || ''} 
                  onChange={e => setFormData({...formData, fullName: e.target.value})}
                  className="w-full bg-black/20 border border-white/10 rounded-lg p-3 text-white focus:outline-none focus:border-blue-500/50" 
                />
              </div>
              <div className="space-y-2">
                <label className="text-xs uppercase tracking-wider text-white/40">National ID (12 Digits)</label>
                <input 
                  value={formData.nationalId || ''} 
                  onChange={e => setFormData({...formData, nationalId: e.target.value})}
                  className="w-full bg-black/20 border border-white/10 rounded-lg p-3 text-white focus:outline-none focus:border-blue-500/50 font-mono tracking-widest" 
                />
              </div>
              <div className="space-y-2">
                <label className="text-xs uppercase tracking-wider text-white/40">Passport Number</label>
                <input 
                  value={formData.passportNumber || ''} 
                  onChange={e => setFormData({...formData, passportNumber: e.target.value})}
                  className="w-full bg-black/20 border border-white/10 rounded-lg p-3 text-white focus:outline-none focus:border-blue-500/50" 
                />
              </div>
              <div className="space-y-2">
                <label className="text-xs uppercase tracking-wider text-white/40">Department</label>
                <input 
                  value={formData.department || ''} 
