             onClick={() => setView('entry')}
            className={`p-3 rounded-2xl transition-all duration-300 group relative ${view === 'entry' ? 'bg-white/10 text-white' : 'text-white/40 hover:text-white hover:bg-white/5'}`}
          >
            <FilePlus size={24} />
            <span className="absolute left-full ml-4 px-2 py-1 bg-black/80 rounded text-xs opacity-0 group-hover:opacity-100 transition-opacity whitespace-nowrap backdrop-blur-sm pointer-events-none">New Entry</span>
