    if (saved) {
      setCache(JSON.parse(saved));
    }
  }, []);

  const addToCache = (entry: BlacklistEntry) => {
    // Need to use functional update to ensure we have latest cache if submitting multiple
    setCache(prev => {
      const newCache = [entry, ...prev].slice(0, 20); 
      localStorage.setItem(CACHE_KEY, JSON.stringify(newCache));
      return newCache;
    });
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      setFiles(Array.from(e.target.files));
    }
  };

  const processImages = async () => {
    if (files.length === 0) return;
    setIsAnalyzing(true);
    try {
      const results = await analyzeDocuments(files);

      if (results.length === 0) {
        setNotification({ msg: 'No valid entries found in the documents.', type: 'error' });
      } else {
        // Add timestamps and default status to all found entries
        const newEntries = results.map(r => ({
          ...r,
          timestamp: new Date().toISOString(),
          status: (r.status as any) || 'Blacklisted'
        }));
        setEntries(newEntries);
        setShowForm(true);
        setNotification({ msg: `Successfully extracted ${newEntries.length} entries.`, type: 'success' });
      }
    } catch (err) {
      setNotification({ msg: 'Failed to analyze documents. Please try again.', type: 'error' });
    } finally {
      setIsAnalyzing(false);
      setTimeout(() => setNotification(null), 4000);
    }
  };

  const updateEntry = (index: number, field: keyof BlacklistEntry, value: string) => {
    const newEntries = [...entries];
    newEntries[index] = { ...newEntries[index], [field]: value };
    setEntries(newEntries);
  };

  const removeEntry = (index: number) => {
    const newEntries = entries.filter((_, i) => i !== index);
    setEntries(newEntries);
    if (newEntries.length === 0) {
      setShowForm(false);
      setFiles([]);
    }
  };

  const handleSubmitAll = async () => {
    setIsSubmitting(true);
    let successCount = 0;
    let failCount = 0;

    // Process all entries
    for (const entry of entries) {
      // Validate and fill defaults
      const finalData: BlacklistEntry = {
        nationalId: entry.nationalId || 'UNKNOWN',
        fullName: entry.fullName || 'UNKNOWN',
        passportNumber: entry.passportNumber || '',
        department: entry.department || '',
        dateOfHire: entry.dateOfHire || '',
        dateOfTermination: entry.dateOfTermination || '',
        reasonForBlacklisting: entry.reasonForBlacklisting || 'Not Specified',
        specificNotes: entry.specificNotes || '',
        status: (entry.status as any) || 'Blacklisted',
        timestamp: new Date().toISOString(),
      };

      const result = await submitToBlacklist(finalData);

      if (result.success) {
        addToCache(finalData);
        successCount++;
      } else {
        failCount++;
      }
    }

    if (failCount === 0) {
      setNotification({ msg: `Successfully logged all ${successCount} entries.`, type: 'success' });
      // Reset
      setFiles([]);
      setShowForm(false);
      setEntries([]);
      setView('dashboard');
    } else {
      setNotification({ msg: `Logged ${successCount} entries. Failed: ${failCount}.`, type: 'error' });
    }

    setIsSubmitting(false);
    setTimeout(() => setNotification(null), 4000);
  };

