    ### EXTRACTION FIELDS ###
    For EACH primary individual found, return an object with:
    - nationalId: (12 digits from THEIR ID card).
    - fullName: (From THEIR ID card as priority).
    - passportNumber: (If present).
    - department: (From application).
    - dateOfHire: (From application).
    - dateOfTermination: (Specific to this person only).
    - reasonForBlacklisting: (Specific to this person only).
    - specificNotes: (Specific to this person only).
    - status: (Defaults to "Blacklisted").

    Return a JSON ARRAY.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview', 
      contents: {
        role: 'user',
        parts: [
          ...fileParts,
          { text: prompt }
        ]
      },
      config: {
        temperature: 0.1, // Low temperature for deterministic, factual extraction
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              nationalId: { type: Type.STRING, description: "12 digit Iraqi National ID" },
              fullName: { type: Type.STRING },
              passportNumber: { type: Type.STRING },
              department: { type: Type.STRING },
              dateOfHire: { type: Type.STRING, description: "YYYY-MM-DD format if possible" },
              dateOfTermination: { type: Type.STRING, description: "YYYY-MM-DD format if possible" },
              reasonForBlacklisting: { type: Type.STRING },
              specificNotes: { type: Type.STRING },
              status: { type: Type.STRING, enum: ["Blacklisted", "Pending Review"] },
            },
            required: ["nationalId", "fullName"]
          }
        }
      }
    });

    const text = response.text;
    if (!text) throw new Error("No response from AI");

    const data = JSON.parse(text);
    // Ensure it's an array, even if AI returns a single object by mistake
    return Array.isArray(data) ? data : [data];

  } catch (error) {
    console.error("Gemini Analysis Error:", error);
    throw new Error("Failed to extract data from documents.");
  }
};

import { GoogleGenAI, Type } from "@google/genai";
import { BlacklistEntry } from "../types";

// Helper to convert file to base64
export const fileToGenerativePart = async (file: File): Promise<{ inlineData: { data: string; mimeType: string } }> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onloadend = () => {
      const base64String = reader.result as string;
      if (!base64String) {
        reject(new Error("Failed to read file"));
        return;
      }
      // Remove data url prefix (e.g. "data:image/jpeg;base64,")
      const base64Data = base64String.split(',')[1];
      resolve({
        inlineData: {
          data: base64Data,
          mimeType: file.type || 'image/jpeg', // Default to jpeg if type missing
        },
      });
    };
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
};

export const analyzeDocuments = async (files: File[]): Promise<Partial<BlacklistEntry>[]> => {
  // Safe access to process.env for browser environments
  let apiKey: string | undefined;
  try {
    apiKey = process.env.API_KEY;
  } catch (e) {
    console.error("Environment variable access failed:", e);
  }

  if (!apiKey) {
    throw new Error("API Key is missing. Ensure process.env.API_KEY is set in your deployment configuration.");
  }

  const ai = new GoogleGenAI({ apiKey });

  const fileParts = await Promise.all(files.map(fileToGenerativePart));

  const prompt = `
    You are an expert HR document analyzer for "Faiz -e- Husaini".

    Analyze the attached images. These images contain documents for MULTIPLE different individuals.
    The images are generally provided in sequential groups.

    Your goal is to perform STRICT data isolation for each individual and extract data into a JSON structure.

    ### CRITICAL RULES ###

    1. **Identify Primary Subjects**:
       - Ignore documents belonging to parents (Mother/Father) included for reference.
       - Extract data ONLY for the actual employee/applicant.

    2. **Strict Data Isolation (No Overlap)**:
       - Treat each person as a completely separate entity. 
       - NEVER copy data (like Dates or Reasons) from one person's documents to another.
       - If Person A has a "Termination Date" on their form/note, and Person B's documents do not show a date, Person B's date MUST be empty. 
       - Do not hallucinate or assume values. 

    3. **Document Clustering**:
       - Group documents visually and logically.

    ### FIELD SPECIFIC RULES ###

    **Full Name Extraction**:
    - **PRIMARY SOURCE**: Extract the Full Name directly from the **National ID Card** where you found the 12-digit National ID.
    - **VERIFICATION**: Check this name against the Application Form.
    - **CONFLICT RESOLUTION**: If the spelling differs between the ID Card and the Form, USE THE SPELLING FROM THE ID CARD.

    ### EXTRACTION FIELDS ###
    For EACH primary individual found, return an object with:
    - nationalId: (12 digits from THEIR ID card).
    - fullName: (From THEIR ID card as priority).
    - passportNumber: (If present).
    - department: (From application).
    - dateOfHire: (From application).
    - dateOfTermination: (Specific to this person only).
    - reasonForBlacklisting: (Specific to this person only).
    - specificNotes: (Specific to this person only).
    - status: (Defaults to "Blacklisted").

    Return a JSON ARRAY.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash', 
      contents: {
        role: 'user',
        parts: [
          ...fileParts,
          { text: prompt }
        ]
      },
      config: {
        temperature: 0.1, // Low temperature for deterministic results
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              nationalId: { type: Type.STRING, description: "12 digit Iraqi National ID" },
              fullName: { type: Type.STRING },
              passportNumber: { type: Type.STRING },
              department: { type: Type.STRING },
              dateOfHire: { type: Type.STRING, description: "YYYY-MM-DD format if possible" },
              dateOfTermination: { type: Type.STRING, description: "YYYY-MM-DD format if possible" },
              reasonForBlacklisting: { type: Type.STRING },
              specificNotes: { type: Type.STRING },
              status: { type: Type.STRING, enum: ["Blacklisted", "Pending Review"] },
            },
            required: ["nationalId", "fullName"]
          }
        }
      }
    });

    const text = response.text;
    if (!text) throw new Error("AI response was empty.");

    try {
      const data = JSON.parse(text);
      // Ensure it's an array
      return Array.isArray(data) ? data : [data];
    } catch (parseError) {
      console.error("JSON Parse Error:", parseError, text);
      throw new Error("Failed to parse AI response.");
    }

  } catch (error: any) {
    console.error("Gemini Analysis Error:", error);
    // Propagate the specific error message if available
    throw new Error(error.message || "Failed to extract data from documents.");
  }
};

import React, { useState, useEffect } from 'react';
import { 
  LayoutDashboard, 
  FilePlus, 
  ScanLine, 
  UploadCloud, 
  CheckCircle2, 
  AlertCircle,
  Loader2,
  Trash2,
  History,
  ShieldAlert,
  Users
} from 'lucide-react';
import { BlacklistEntry, ViewState } from './types';
import { analyzeDocuments } from './services/geminiService';
import { submitToBlacklist } from './services/webhookService';
import { GlassCard } from './components/GlassCard';

// Constants
const CACHE_KEY = 'faiz_blacklist_cache';

const App: React.FC = () => {
  const [view, setView] = useState<ViewState>('dashboard');
  const [cache, setCache] = useState<BlacklistEntry[]>([]);

  // Form State
  const [files, setFiles] = useState<File[]>([]);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);

  // Changed from single formData to an array of entries
  const [entries, setEntries] = useState<Partial<BlacklistEntry>[]>([]);
  const [showForm, setShowForm] = useState(false);
  const [notification, setNotification] = useState<{msg: string, type: 'success' | 'error'} | null>(null);

  useEffect(() => {
    // Load cache on mount
    const saved = localStorage.getItem(CACHE_KEY);
    if (saved) {
      setCache(JSON.parse(saved));
    }
  }, []);

  const addToCache = (entry: BlacklistEntry) => {
    // Need to use functional update to ensure we have latest cache if submitting multiple
    setCache(prev => {
      const newCache = [entry, ...prev].slice(0, 20); 
      localStorage.setItem(CACHE_KEY, JSON.stringify(newCache));
      return newCache;
    });
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      setFiles(Array.from(e.target.files));
    }
  };

  const processImages = async () => {
    if (files.length === 0) return;
    setIsAnalyzing(true);
    setNotification(null);
    try {
      const results = await analyzeDocuments(files);

      if (results.length === 0) {
        setNotification({ msg: 'No valid entries found in the documents.', type: 'error' });
      } else {
        // Add timestamps and default status to all found entries
        const newEntries = results.map(r => ({
          ...r,
          timestamp: new Date().toISOString(),
          status: (r.status as any) || 'Blacklisted'
        }));
        setEntries(newEntries);
        setShowForm(true);
        setNotification({ msg: `Successfully extracted ${newEntries.length} entries.`, type: 'success' });
      }
    } catch (err: any) {
      console.error("Processing Error:", err);
      // Display the actual error message (e.g., API Key missing)
      setNotification({ 
        msg: err.message || 'Failed to analyze documents. Please check console.', 
        type: 'error' 
      });
    } finally {
      setIsAnalyzing(false);
      // Don't auto-dismiss errors immediately so user can read them
      setTimeout(() => {
        setNotification(prev => prev?.type === 'success' ? null : prev);
      }, 6000);
    }
  };

  const updateEntry = (index: number, field: keyof BlacklistEntry, value: string) => {
    const newEntries = [...entries];
    newEntries[index] = { ...newEntries[index], [field]: value };
    setEntries(newEntries);
  };

  const removeEntry = (index: number) => {
    const newEntries = entries.filter((_, i) => i !== index);
    setEntries(newEntries);
    if (newEntries.length === 0) {
      setShowForm(false);
      setFiles([]);
    }
  };

  const handleSubmitAll = async () => {
    setIsSubmitting(true);
    let successCount = 0;
    let failCount = 0;

    // Process all entries
    for (const entry of entries) {
      // Validate and fill defaults
      const finalData: BlacklistEntry = {
        nationalId: entry.nationalId || 'UNKNOWN',
        fullName: entry.fullName || 'UNKNOWN',
        passportNumber: entry.passportNumber || '',
        department: entry.department || '',
        dateOfHire: entry.dateOfHire || '',
        dateOfTermination: entry.dateOfTermination || '',
        reasonForBlacklisting: entry.reasonForBlacklisting || 'Not Specified',
        specificNotes: entry.specificNotes || '',
        status: (entry.status as any) || 'Blacklisted',
        timestamp: new Date().toISOString(),
      };

      const result = await submitToBlacklist(finalData);

      if (result.success) {
        addToCache(finalData);
        successCount++;
      } else {
        failCount++;
      }
    }

    if (failCount === 0) {
      setNotification({ msg: `Successfully logged all ${successCount} entries.`, type: 'success' });
      // Reset
      setFiles([]);
      setShowForm(false);
      setEntries([]);
      setView('dashboard');
    } else {
      setNotification({ msg: `Logged ${successCount} entries. Failed: ${failCount}.`, type: 'error' });
    }

    setIsSubmitting(false);
    setTimeout(() => setNotification(null), 4000);
  };

