        role: 'user',
        parts: [
          ...fileParts,
          { text: prompt }
        ]
      },
      config: {
        temperature: 0.1, // Keep low to prevent hallucinations, but high enough to interpret handwriting
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              nationalId: { type: Type.STRING, description: "12-digit ID from the linked ID Card" },
              fullName: { type: Type.STRING, description: "Name from the linked ID Card" },
              passportNumber: { type: Type.STRING },
              department: { type: Type.STRING },
              dateOfHire: { type: Type.STRING },
              dateOfTermination: { type: Type.STRING, description: "YYYY-MM-DD" },
              reasonForBlacklisting: { type: Type.STRING, description: "The specific violation found on the Yellow Sticky Note" },
              specificNotes: { type: Type.STRING, description: "Verbatim transcription of the Yellow Sticky Note" },
              status: { type: Type.STRING, enum: ["Blacklisted", "Pending Review"] },
            },
            required: ["nationalId", "fullName", "reasonForBlacklisting", "specificNotes"]
          }
        }
      }
    });

    const text = response.text;
    if (!text) throw new Error("AI response was empty.");

    try {
      const data = JSON.parse(text);
      return Array.isArray(data) ? data : [data];
    } catch (parseError) {
      console.error("JSON Parse Error:", parseError, text);
      throw new Error("Failed to parse AI response.");
    }

  } catch (error: any) {
    console.error("Gemini Analysis Error:", error);
    throw new Error(error.message || "Failed to extract data from documents.");
  }
};

