import { GoogleGenAI, Type } from "@google/genai";
import { BlacklistEntry } from "../types";

// --- Image Optimization Configuration ---
// High resolution is critical for reading handwriting and small ID numbers.
const MAX_IMAGE_DIMENSION = 2048; 
const JPEG_QUALITY = 0.90; // Increased quality to ensure handwriting on sticky notes is clear

/**
 * Resizes and compresses an image file before sending to Gemini.
 */
export const fileToGenerativePart = async (file: File): Promise<{ inlineData: { data: string; mimeType: string } }> => {
  return new Promise((resolve, reject) => {
    // If not an image (unlikely given input accept), just pass it through
    if (!file.type.startsWith('image/')) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const base64String = reader.result as string;
        const base64Data = base64String.split(',')[1];
        resolve({ inlineData: { data: base64Data, mimeType: file.type } });
      };
      reader.onerror = reject;
      reader.readAsDataURL(file);
      return;
    }

    const img = new Image();
    const reader = new FileReader();

    reader.onload = (e) => {
      img.src = e.target?.result as string;
    };
    reader.onerror = reject;

    img.onload = () => {
      let width = img.width;
      let height = img.height;

      // Calculate new dimensions while maintaining aspect ratio
      if (width > height) {
        if (width > MAX_IMAGE_DIMENSION) {
          height *= MAX_IMAGE_DIMENSION / width;
          width = MAX_IMAGE_DIMENSION;
        }
      } else {
        if (height > MAX_IMAGE_DIMENSION) {
          width *= MAX_IMAGE_DIMENSION / height;
          height = MAX_IMAGE_DIMENSION;
        }
      }

      const canvas = document.createElement('canvas');
      canvas.width = width;
      canvas.height = height;
      const ctx = canvas.getContext('2d');

      if (!ctx) {
        reject(new Error("Browser does not support canvas context"));
        return;
      }

      // Draw and compress
      ctx.drawImage(img, 0, 0, width, height);

      // Convert to JPEG
      const dataUrl = canvas.toDataURL('image/jpeg', JPEG_QUALITY);

      // Remove prefix "data:image/jpeg;base64,"
      const base64Data = dataUrl.split(',')[1];

      resolve({
        inlineData: {
          data: base64Data,
          mimeType: 'image/jpeg', 
        },
      });
    };

    reader.readAsDataURL(file);
  });
};

export const analyzeDocuments = async (files: File[]): Promise<Partial<BlacklistEntry>[]> => {
  let apiKey: string | undefined;
  try {
    apiKey = process.env.API_KEY;
  } catch (e) {
    console.error("Environment variable access failed:", e);
  }

  if (!apiKey) {
    throw new Error("API Key is missing. Ensure process.env.API_KEY is set in your deployment configuration.");
  }

  const ai = new GoogleGenAI({ apiKey });

  const fileParts = await Promise.all(files.map(fileToGenerativePart));

  const prompt = `
    You are an expert HR Forensics Auditor. You are processing images that contain "Identity Cards" and "Termination Forms".

    ### YOUR MISSION
    For every individual person found in these images, you must create a single record that combines their Identity (from the ID Card) with their Violation (from the Termination Form).

    ### STEP 1: VISUAL ENTITY MATCHING (CRITICAL)
    1. Look at the photo on a **Termination Form**.
    2. Find the **ID Card** that has the exact same person's face.
    3. Link these two documents together. 
    *WARNING*: Do not mix up the Sticky Notes. The Sticky Note on a specific Termination Form applies ONLY to the person pictured on THAT specific form.

    ### STEP 2: DATA EXTRACTION

    **A. The Violation & Reason (SOURCE: The Yellow Sticky Note)**
    - Locate the **Yellow Sticky Note** attached to the Termination Form.
    - **TRANSCRIPTION**: Read the handwritten text on this sticky note. It is the primary source of truth.
    - If the note is in **Arabic**, translate the core meaning to English for the 'reasonForBlacklisting' field.
    - If the note is in **English**, transcribe it exactly.
    - **field: specificNotes**: Transcribe the FULL content of the sticky note verbatim (include Arabic if present).
    - **field: reasonForBlacklisting**: Extract the short summary (e.g., "Caught Stealing", "Fighting", "Forgery"). *If this field is empty, you have failed.*

    **B. The Termination Date (SOURCE: The Yellow Sticky Note)**
    - Look for a date written on the Sticky Note or the handwritten margin.
    - Format is usually **DD/MM/YY** (e.g., "4/12/25" = Dec 4th, 2025).
    - Convert to YYYY-MM-DD.
    - If no date is on the note, look for a stamped date on the document.

    **C. The Identity (SOURCE: The ID Card)**
    - **CONSTRAINT**: You must extract the Name and ID Number from the **SAME PHYSICAL CARD**. Do not mix data from the form and the card for this section.
    - **National ID**: The 12-digit number (e.g., 199... or 200...) found on the card.
    - **Full Name**: 
      1. Look at the **ID Card** (NOT the form).
      2. If the English name is printed on the card, use it exactly.
      3. If only Arabic is present, transliterate the Arabic name found on the **ID Card** to English.
      4. *Do not use the handwritten name on the termination form as the primary legal name.*

    ### OUTPUT FORMAT
    Return a JSON Array of objects.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview', // LOCKED IN: Using Gemini 3 Pro Preview
      contents: {
        role: 'user',
        parts: [
          ...fileParts,
          { text: prompt }
        ]
      },
      config: {
        temperature: 0.1, // Keep low to prevent hallucinations, but high enough to interpret handwriting
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              nationalId: { type: Type.STRING, description: "12-digit ID from the linked ID Card" },
              fullName: { type: Type.STRING, description: "Name extracted directly from the ID Card" },
              passportNumber: { type: Type.STRING },
              department: { type: Type.STRING },
              dateOfHire: { type: Type.STRING },
              dateOfTermination: { type: Type.STRING, description: "YYYY-MM-DD" },
              reasonForBlacklisting: { type: Type.STRING, description: "The specific violation found on the Yellow Sticky Note" },
              specificNotes: { type: Type.STRING, description: "Verbatim transcription of the Yellow Sticky Note" },
              status: { type: Type.STRING, enum: ["Blacklisted", "Pending Review"] },
            },
            required: ["nationalId", "fullName", "reasonForBlacklisting", "specificNotes"]
          }
        }
      }
    });

    let text = response.text;
    if (!text) throw new Error("AI response was empty.");

    // Clean up potential Markdown code blocks if the model adds them (e.g. ```json ... ```)
    text = text.replace(/^```json/, '').replace(/^```/, '').replace(/```$/, '');

    try {
      const data = JSON.parse(text);
      return Array.isArray(data) ? data : [data];
    } catch (parseError) {
      console.error("JSON Parse Error:", parseError, text);
      throw new Error("Failed to parse AI response.");
    }

  } catch (error: any) {
    console.error("Gemini Analysis Error:", error);
    throw new Error(error.message || "Failed to extract data from documents.");
  }
};

