              dateOfHire: { type: Type.STRING },
              dateOfTermination: { type: Type.STRING, description: "YYYY-MM-DD" },
              reasonForBlacklisting: { type: Type.STRING, description: "The specific violation found on the Yellow Sticky Note" },
              specificNotes: { type: Type.STRING, description: "Verbatim transcription of the Yellow Sticky Note" },
              status: { type: Type.STRING, enum: ["Blacklisted", "Pending Review"] },
            },
            required: ["nationalId", "fullName", "reasonForBlacklisting", "specificNotes"]
          }
        }
      }
    });

    let text = response.text;
    if (!text) throw new Error("AI response was empty.");

    // Clean up potential Markdown code blocks if the model adds them
    text = text.replace(/^```json/, '').replace(/^```/, '').replace(/```$/, '');

    try {
      const data = JSON.parse(text);
      return Array.isArray(data) ? data : [data];
    } catch (parseError) {
      console.error("JSON Parse Error:", parseError, text);
      throw new Error("Failed to parse AI response.");
    }

  } catch (error: any) {
    console.error("Gemini Analysis Error:", error);
    throw new Error(error.message || "Failed to extract data from documents.");
  }
};

import { GoogleGenAI, Type } from "@google/genai";
import { BlacklistEntry } from "../types";

// --- Image Optimization Configuration ---
// High resolution is critical for reading handwriting and small ID numbers.
const MAX_IMAGE_DIMENSION = 2048; 
const JPEG_QUALITY = 0.90; // Increased quality to ensure handwriting on sticky notes is clear

/**
 * Resizes and compresses an image file before sending to Gemini.
 */
export const fileToGenerativePart = async (file: File): Promise<{ inlineData: { data: string; mimeType: string } }> => {
  return new Promise((resolve, reject) => {
    // If not an image (unlikely given input accept), just pass it through
    if (!file.type.startsWith('image/')) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const base64String = reader.result as string;
        const base64Data = base64String.split(',')[1];
        resolve({ inlineData: { data: base64Data, mimeType: file.type } });
      };
      reader.onerror = reject;
      reader.readAsDataURL(file);
      return;
    }

    const img = new Image();
    const reader = new FileReader();

    reader.onload = (e) => {
      img.src = e.target?.result as string;
    };
    reader.onerror = reject;

    img.onload = () => {
      let width = img.width;
      let height = img.height;

      // Calculate new dimensions while maintaining aspect ratio
      if (width > height) {
        if (width > MAX_IMAGE_DIMENSION) {
          height *= MAX_IMAGE_DIMENSION / width;
          width = MAX_IMAGE_DIMENSION;
        }
      } else {
        if (height > MAX_IMAGE_DIMENSION) {
          width *= MAX_IMAGE_DIMENSION / height;
          height = MAX_IMAGE_DIMENSION;
        }
      }

      const canvas = document.createElement('canvas');
      canvas.width = width;
      canvas.height = height;
      const ctx = canvas.getContext('2d');

      if (!ctx) {
        reject(new Error("Browser does not support canvas context"));
        return;
      }

      // Draw and compress
      ctx.drawImage(img, 0, 0, width, height);

      // Convert to JPEG
      const dataUrl = canvas.toDataURL('image/jpeg', JPEG_QUALITY);

      // Remove prefix "data:image/jpeg;base64,"
      const base64Data = dataUrl.split(',')[1];

      resolve({
        inlineData: {
          data: base64Data,
          mimeType: 'image/jpeg', 
        },
      });
    };

    reader.readAsDataURL(file);
  });
};

export const analyzeDocuments = async (files: File[]): Promise<Partial<BlacklistEntry>[]> => {
  let apiKey: string | undefined;
  try {
    apiKey = process.env.API_KEY;
  } catch (e) {
    console.error("Environment variable access failed:", e);
  }

  if (!apiKey) {
    throw new Error("API Key is missing. Ensure process.env.API_KEY is set in your deployment configuration.");
  }

  const ai = new GoogleGenAI({ apiKey });

  const fileParts = await Promise.all(files.map(fileToGenerativePart));

  const prompt = `
    You are a specialized Data Entry Verification Bot. You are processing images that contain ID Cards and Termination Forms.

    ### CRITICAL ISSUE FIX: MIXED NAMES
    Previous scans have incorrectly mixed the First Name of "Person A" with the Last Name of "Person B".
    To fix this, you must follow the **VISUAL ANCHOR PROTOCOL** below.

    ### EXECUTION STEPS (Perform in strict order)

    **STEP 1: ANCHOR TO THE ID CARD**
    1. Ignore all paper forms initially. Look ONLY at the plastic ID Cards.
    2. Find a specific ID Card.
    3. Extract the **National ID Number** (12 digits) from that card.
    4. **VISUAL ANCHOR**: Without moving your "eyes" from that specific card, read the Name printed **immediately next to or above** that ID number.
       - **Constraint**: Do not jump to a different card.
       - **Constraint**: Do not read from the paper form underneath.
       - **Constraint**: If English text is present on the card, use it. If only Arabic is present on the card, transliterate it.
    5. Store this [Name + ID] combination as a "Locked Identity".

    **STEP 2: LINK VIOLATION DATA**
    1. Now look at the paper Termination Forms.
    2. Find the form with a photo that matches the face on the "Locked Identity" card.
    3. Locate the **Yellow Sticky Note** on that specific form.
    4. Extract:
       - **reasonForBlacklisting**: Summary of the handwritten note.
       - **specificNotes**: Verbatim transcription of the note.
       - **dateOfTermination**: Date found on the note (format YYYY-MM-DD).

    ### OUTPUT FORMAT
    Return a JSON Array. Each object must represent ONE "Locked Identity" with their corresponding violation data.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview', // LOCKED IN: Using Gemini 3 Pro Preview
      contents: {
        role: 'user',
        parts: [
          ...fileParts,
          { text: prompt }
        ]
      },
      config: {
        temperature: 0.1, // Low temperature is essential for deterministic OCR
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              nationalId: { type: Type.STRING, description: "12-digit ID from the anchored ID Card" },
              fullName: { type: Type.STRING, description: "Name printed physically on the SAME card as the ID number" },
              passportNumber: { type: Type.STRING },
              department: { type: Type.STRING },
              dateOfHire: { type: Type.STRING },
              dateOfTermination: { type: Type.STRING, description: "YYYY-MM-DD" },
              reasonForBlacklisting: { type: Type.STRING, description: "Violation from the matching sticky note" },
              specificNotes: { type: Type.STRING, description: "Verbatim note content" },
              status: { type: Type.STRING, enum: ["Blacklisted", "Pending Review"] },
            },
            required: ["nationalId", "fullName", "reasonForBlacklisting", "specificNotes"]
          }
        }
      }
    });

    let text = response.text;
    if (!text) throw new Error("AI response was empty.");

    // Clean up potential Markdown code blocks if the model adds them
    text = text.replace(/^```json/, '').replace(/^```/, '').replace(/```$/, '');

    try {
      const data = JSON.parse(text);
      return Array.isArray(data) ? data : [data];
    } catch (parseError) {
      console.error("JSON Parse Error:", parseError, text);
      throw new Error("Failed to parse AI response.");
    }

  } catch (error: any) {
    console.error("Gemini Analysis Error:", error);
    throw new Error(error.message || "Failed to extract data from documents.");
  }
};

import React, { useState, useEffect } from 'react';
import { 
  LayoutDashboard, 
  FilePlus, 
  ScanLine, 
  UploadCloud, 
  CheckCircle2, 
  AlertCircle,
  Loader2,
  Trash2,
  History,
  ShieldAlert,
  Users
} from 'lucide-react';
import { BlacklistEntry, ViewState } from './types';
import { analyzeDocuments } from './services/geminiService';
import { submitToBlacklist } from './services/webhookService';
import { GlassCard } from './components/GlassCard';

// Constants
const CACHE_KEY = 'faiz_blacklist_cache';

const App: React.FC = () => {
  const [view, setView] = useState<ViewState>('dashboard');
  const [cache, setCache] = useState<BlacklistEntry[]>([]);

  // Form State
  const [files, setFiles] = useState<File[]>([]);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [uploadProgress, setUploadProgress] = useState<{ current: number; total: number } | null>(null);

  // Changed from single formData to an array of entries
  const [entries, setEntries] = useState<Partial<BlacklistEntry>[]>([]);
  const [showForm, setShowForm] = useState(false);
  const [notification, setNotification] = useState<{msg: string, type: 'success' | 'error'} | null>(null);

  useEffect(() => {
    // Load cache on mount
    const saved = localStorage.getItem(CACHE_KEY);
    if (saved) {
      setCache(JSON.parse(saved));
    }
  }, []);

  const addToCache = (entry: BlacklistEntry) => {
    // Need to use functional update to ensure we have latest cache if submitting multiple
    setCache(prev => {
      const newCache = [entry, ...prev].slice(0, 20); 
      localStorage.setItem(CACHE_KEY, JSON.stringify(newCache));
      return newCache;
    });
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      setFiles(Array.from(e.target.files));
    }
  };

  const processImages = async () => {
    if (files.length === 0) return;
    setIsAnalyzing(true);
    setNotification(null);
    try {
      const results = await analyzeDocuments(files);

      if (results.length === 0) {
        setNotification({ msg: 'No valid entries found in the documents.', type: 'error' });
      } else {
        // Add timestamps and default status to all found entries
        const newEntries = results.map(r => ({
          ...r,
          timestamp: new Date().toISOString(),
          status: (r.status as any) || 'Blacklisted'
        }));
        setEntries(newEntries);
        setShowForm(true);
        setNotification({ msg: `Successfully extracted ${newEntries.length} entries.`, type: 'success' });
      }
    } catch (err: any) {
      console.error("Processing Error:", err);
      // Display the actual error message (e.g., API Key missing)
      setNotification({ 
        msg: err.message || 'Failed to analyze documents. Please check console.', 
        type: 'error' 
      });
    } finally {
      setIsAnalyzing(false);
      // Don't auto-dismiss errors immediately so user can read them
      setTimeout(() => {
        setNotification(prev => prev?.type === 'success' ? null : prev);
      }, 6000);
    }
  };

  const updateEntry = (index: number, field: keyof BlacklistEntry, value: string) => {
    const newEntries = [...entries];
    newEntries[index] = { ...newEntries[index], [field]: value };
    setEntries(newEntries);
  };

  const removeEntry = (index: number) => {
    const newEntries = entries.filter((_, i) => i !== index);
    setEntries(newEntries);
    if (newEntries.length === 0) {
      setShowForm(false);
      setFiles([]);
    }
  };

  const delay = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

  const handleSubmitAll = async () => {
    setIsSubmitting(true);
    let successCount = 0;
    let failCount = 0;
    const total = entries.length;

    // Initialize progress
    setUploadProgress({ current: 0, total });

    // Process all entries sequentially with delay
    for (let i = 0; i < total; i++) {
      // Update UI to show we are processing the (i+1)th entry
      setUploadProgress({ current: i + 1, total });

      const entry = entries[i];
      // Validate and fill defaults
      const finalData: BlacklistEntry = {
        nationalId: entry.nationalId || 'UNKNOWN',
        fullName: entry.fullName || 'UNKNOWN',
        passportNumber: entry.passportNumber || '',
        department: entry.department || '',
        dateOfHire: entry.dateOfHire || '',
        dateOfTermination: entry.dateOfTermination || '',
        reasonForBlacklisting: entry.reasonForBlacklisting || 'Not Specified',
        specificNotes: entry.specificNotes || '',
        status: (entry.status as any) || 'Blacklisted',
        timestamp: new Date().toISOString(),
      };

      const result = await submitToBlacklist(finalData);

      if (result.success) {
        addToCache(finalData);
        successCount++;
      } else {
        failCount++;
      }

      // Add a 1.5 second delay between requests to prevent database locks,
      // unless it's the last item.
      if (i < total - 1) {
        await delay(1500);
      }
    }

    if (failCount === 0) {
      setNotification({ msg: `Successfully logged all ${successCount} entries.`, type: 'success' });
      // Reset
      setFiles([]);
      setShowForm(false);
      setEntries([]);
      setView('dashboard');
    } else {
      setNotification({ msg: `Logged ${successCount} entries. Failed: ${failCount}.`, type: 'error' });
    }

    setIsSubmitting(false);
    setUploadProgress(null);
    setTimeout(() => setNotification(null), 4000);
  };

  // --- Views ---

  const renderDashboard = () => (
    <div className="space-y-6 animate-in fade-in duration-500">
      <div className="flex justify-between items-end">
        <div>
          <h2 className="text-3xl font-thin text-white tracking-tight">Recent Activity</h2>
          <p className="text-white/50 mt-1 font-light">Last 20 Logged Entries</p>
        </div>
        <button 
          onClick={() => setView('entry')}
          className="bg-blue-600 hover:bg-blue-500 text-white px-6 py-2 rounded-full font-medium transition-all shadow-lg hover:shadow-blue-500/25 flex items-center gap-2"
        >
          <FilePlus size={18} /> New Entry
        </button>
      </div>

      <div className="grid gap-4">
        {cache.length === 0 ? (
          <GlassCard className="p-12 flex flex-col items-center justify-center text-white/30">
            <History size={48} className="mb-4" />
            <p>No recent blacklist logs found.</p>
          </GlassCard>
        ) : (
          cache.map((entry, idx) => (
            <GlassCard key={idx} className="p-6 flex items-center justify-between group hover:border-white/40">
              <div className="flex items-center gap-4">
                <div className="w-12 h-12 rounded-full bg-red-500/20 flex items-center justify-center text-red-400">
                  <ShieldAlert size={20} />
                </div>
                <div>
                  <h3 className="font-semibold text-lg">{entry.fullName}</h3>
                  <p className="text-white/50 text-sm font-mono">{entry.nationalId}</p>
                </div>
              </div>
              <div className="text-right">
                <span className="inline-block px-3 py-1 rounded-full bg-red-500/20 text-red-300 text-xs font-bold border border-red-500/30">
                  {entry.status}
                </span>
                <p className="text-white/40 text-xs mt-2">{new Date(entry.timestamp).toLocaleDateString()}</p>
              </div>
            </GlassCard>
          ))
        )}
      </div>
    </div>
  );

  const renderEntry = () => (
    <div className="max-w-5xl mx-auto space-y-8 animate-in slide-in-from-bottom-4 duration-500 pb-20">
      <div className="flex items-center gap-4 mb-8">
        <button onClick={() => setView('dashboard')} className="text-white/50 hover:text-white transition-colors">
          &larr; Back
        </button>
        <h2 className="text-3xl font-thin text-white tracking-tight">New Blacklist Entry</h2>
      </div>

      {!showForm ? (
        <GlassCard className="p-12 border-dashed border-2 border-white/20 hover:border-white/40 transition-all text-center">
           <input 
              type="file" 
              multiple 
              accept="image/*" 
              onChange={handleFileUpload} 
              className="hidden" 
              id="file-upload"
            />
            <label htmlFor="file-upload" className="cursor-pointer flex flex-col items-center">
              <div className="w-20 h-20 rounded-full bg-blue-500/20 flex items-center justify-center text-blue-400 mb-6">
                <UploadCloud size={40} />
              </div>
              <h3 className="text-2xl font-medium mb-2">Drop Documents (Batch Supported)</h3>
              <p className="text-white/50 max-w-md mx-auto mb-8">
                Upload National IDs and Application forms. You can upload multiple files for multiple people at once.
              </p>

              {files.length > 0 && (
                <div className="mb-6 flex flex-wrap gap-2 justify-center max-w-xl mx-auto">
                  {files.map((f, i) => (
                    <span key={i} className="px-3 py-1 rounded bg-white/10 text-xs border border-white/10">{f.name}</span>
                  ))}
                </div>
              )}

              <button 
                onClick={processImages}
                disabled={files.length === 0 || isAnalyzing}
                className={`
                  px-8 py-3 rounded-full font-medium text-lg flex items-center gap-2 shadow-xl transition-all
                  ${files.length > 0 ? 'bg-white text-black hover:bg-white/90 transform hover:scale-105' : 'bg-white/10 text-white/30 cursor-not-allowed'}
                `}
              >
                {isAnalyzing ? <Loader2 className="animate-spin" /> : <ScanLine />}
                {isAnalyzing ? 'Analyzing Batch...' : 'Extract & Process'}
              </button>
            </label>
        </GlassCard>
      ) : (
        <div className="space-y-8">
          <div className="flex justify-between items-center">
             <h3 className="text-xl text-blue-300 flex items-center gap-2">
               <Users size={24} /> 
               Review Detected Entries ({entries.length})
             </h3>
             <button 
                onClick={() => { setShowForm(false); setFiles([]); setEntries([]); }}
                className="text-white/40 hover:text-white text-sm"
              >
                Cancel All
              </button>
          </div>

          {entries.map((entry, index) => (
            <GlassCard key={index} className="p-6 relative group border-white/10 hover:border-blue-500/30">
               {/* Entry Header with Remove Button */}
               <div className="absolute top-4 right-4">
                 <button 
                   onClick={() => removeEntry(index)}
                   className="p-2 rounded-full hover:bg-red-500/20 text-white/20 hover:text-red-400 transition-colors"
                   title="Remove this entry"
                 >
                   <Trash2 size={18} />
                 </button>
               </div>

               <div className="mb-6 border-b border-white/5 pb-4">
                  <span className="text-xs uppercase tracking-widest text-blue-400 font-bold mb-1 block">Entry #{index + 1}</span>
               </div>

               <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                 {/* Left Column: Personal Data */}
                 <div className="space-y-4">
                   <h4 className="text-sm font-medium text-white/60 mb-2 flex items-center gap-2"><CheckCircle2 size={14}/> Identity & Employment</h4>
                   <div className="grid grid-cols-2 gap-3">
                      <div className="col-span-2">
                        <label className="text-[10px] uppercase tracking-wider text-white/30">Full Name</label>
                        <input 
                          value={entry.fullName || ''} 
                          onChange={e => updateEntry(index, 'fullName', e.target.value)}
                          className="w-full bg-black/20 border border-white/10 rounded-lg p-2 text-white focus:outline-none focus:border-blue-500/50" 
                        />
                      </div>
                      <div className="col-span-2">
                        <label className="text-[10px] uppercase tracking-wider text-white/30">National ID</label>
                        <input 
                          value={entry.nationalId || ''} 
                          onChange={e => updateEntry(index, 'nationalId', e.target.value)}
                          className="w-full bg-black/20 border border-white/10 rounded-lg p-2 text-white focus:outline-none focus:border-blue-500/50 font-mono tracking-widest" 
