                      </div>
                      <div>
                        <label className="text-[10px] uppercase tracking-wider text-white/30">Passport</label>
                        <input 
                          value={entry.passportNumber || ''} 
                          onChange={e => updateEntry(index, 'passportNumber', e.target.value)}
                          className="w-full bg-black/20 border border-white/10 rounded-lg p-2 text-white focus:outline-none focus:border-blue-500/50" 
                        />
                      </div>
                      <div>
                        <label className="text-[10px] uppercase tracking-wider text-white/30">Department</label>
                        <input 
                          value={entry.department || ''} 
                          onChange={e => updateEntry(index, 'department', e.target.value)}
                          className="w-full bg-black/20 border border-white/10 rounded-lg p-2 text-white focus:outline-none focus:border-blue-500/50" 
                        />
                      </div>
                      <div>
                        <label className="text-[10px] uppercase tracking-wider text-white/30">Hire Date</label>
                        <input 
                          value={entry.dateOfHire || ''} 
                          onChange={e => updateEntry(index, 'dateOfHire', e.target.value)}
                          className="w-full bg-black/20 border border-white/10 rounded-lg p-2 text-white focus:outline-none focus:border-blue-500/50" 
                        />
                      </div>
                      <div>
                        <label className="text-[10px] uppercase tracking-wider text-white/30">Term. Date</label>
                        <input 
                          value={entry.dateOfTermination || ''} 
                          onChange={e => updateEntry(index, 'dateOfTermination', e.target.value)}
                          className="w-full bg-black/20 border border-white/10 rounded-lg p-2 text-white focus:outline-none focus:border-blue-500/50" 
                        />
                      </div>
                   </div>
                 </div>

                 {/* Right Column: Blacklist Info */}
                 <div className="space-y-4">
                   <h4 className="text-sm font-medium text-red-300/60 mb-2 flex items-center gap-2"><ShieldAlert size={14}/> Violation Details</h4>
                   <div className="space-y-3">
                      <div>
                        <label className="text-[10px] uppercase tracking-wider text-white/30">Reason</label>
                        <input 
                          value={entry.reasonForBlacklisting || ''} 
                          onChange={e => updateEntry(index, 'reasonForBlacklisting', e.target.value)}
                          className="w-full bg-red-500/10 border border-red-500/30 rounded-lg p-2 text-red-100 focus:outline-none focus:border-red-500" 
                        />
                      </div>
                      <div>
                        <label className="text-[10px] uppercase tracking-wider text-white/30">Notes</label>
                        <textarea 
                          rows={4}
                          value={entry.specificNotes || ''} 
                          onChange={e => updateEntry(index, 'specificNotes', e.target.value)}
                          className="w-full bg-black/20 border border-white/10 rounded-lg p-2 text-white focus:outline-none focus:border-blue-500/50 resize-none text-sm" 
                        />
                      </div>
                      <div>
                         <label className="text-[10px] uppercase tracking-wider text-white/30">Status</label>
