                         >
                           <option value="Blacklisted">Blacklisted</option>
                           <option value="Pending Review">Pending Review</option>
                         </select>
                      </div>
                   </div>
                 </div>
               </div>
            </GlassCard>
          ))}

          <div className="fixed bottom-0 left-24 right-0 p-6 bg-black/80 backdrop-blur-md border-t border-white/10 flex justify-end gap-4 z-40">
             <div className="flex items-center mr-auto text-white/40 text-sm">
                <ShieldAlert size={16} className="mr-2"/>
