                className="bg-red-600 hover:bg-red-500 text-white px-8 py-3 rounded-full font-medium transition-all shadow-lg hover:shadow-red-600/25 flex items-center gap-2 relative overflow-hidden"
              >
                {isSubmitting && uploadProgress && (
                  <div 
                    className="absolute left-0 top-0 bottom-0 bg-white/20 transition-all duration-300"
                    style={{ width: `${(uploadProgress.current / uploadProgress.total) * 100}%` }}
