            radial-gradient(circle at 10% 20%, rgba(20, 0, 50, 0.8) 0%, transparent 60%),
            radial-gradient(circle at 90% 80%, rgba(0, 40, 80, 0.8) 0%, transparent 60%),
            linear-gradient(to bottom, #050505, #0a0a12)
          `
        }}
      />

      {/* Notification Toast */}
      {notification && (
        <div className={`
          fixed top-6 left-1/2 transform -translate-x-1/2 z-[60] px-6 py-3 rounded-full backdrop-blur-xl border shadow-2xl flex items-center gap-3 animate-in slide-in-from-top-full
