            <span className="absolute left-full ml-4 px-2 py-1 bg-black/80 rounded text-xs opacity-0 group-hover:opacity-100 transition-opacity whitespace-nowrap backdrop-blur-sm pointer-events-none">Dashboard</span>
          </button>

          <button 
             onClick={() => setView('entry')}
            className={`p-3 rounded-2xl transition-all duration-300 group relative ${view === 'entry' ? 'bg-white/10 text-white' : 'text-white/40 hover:text-white hover:bg-white/5'}`}
          >
            <FilePlus size={24} />
            <span className="absolute left-full ml-4 px-2 py-1 bg-black/80 rounded text-xs opacity-0 group-hover:opacity-100 transition-opacity whitespace-nowrap backdrop-blur-sm pointer-events-none">New Entry</span>
          </button>
        </nav>

        {/* Content Area */}
        <main className="flex-1 p-8 overflow-y-auto z-10 relative">
          <header className="mb-8 flex justify-between items-center">
            <div>
              <h1 className="text-lg font-medium text-white/80">Faiz-e-Husaini HR Operations</h1>
              <p className="text-xs text-white/30 uppercase tracking-widest mt-1">Secure Log System v26.0</p>
            </div>
            <div className="flex items-center gap-3">
               <div className="w-8 h-8 rounded-full bg-gradient-to-tr from-gray-700 to-gray-600 border border-white/20"></div>
            </div>
          </header>

          {view === 'dashboard' && renderDashboard()}
          {view === 'entry' && renderEntry()}
        </main>
      </div>
    </div>
  );
};

