                          onChange={e => updateEntry(index, 'fullName', e.target.value)}
                          className="w-full bg-black/20 border border-white/10 rounded-lg p-2 text-white focus:outline-none focus:border-blue-500/50" 
                        />
                      </div>
                      <div className="col-span-2">
                        <label className="text-[10px] uppercase tracking-wider text-white/30">National ID</label>
                        <input 
                          value={entry.nationalId || ''} 
                          onChange={e => updateEntry(index, 'nationalId', e.target.value)}
                          className="w-full bg-black/20 border border-white/10 rounded-lg p-2 text-white focus:outline-none focus:border-blue-500/50 font-mono tracking-widest" 
