                   <h4 className="text-sm font-medium text-red-300/60 mb-2 flex items-center gap-2"><ShieldAlert size={14}/> Violation Details</h4>
                   <div className="space-y-3">
                      <div>
                        <label className="text-[10px] uppercase tracking-wider text-white/30">Reason</label>
                        <input 
                          value={entry.reasonForBlacklisting || ''} 
                          onChange={e => updateEntry(index, 'reasonForBlacklisting', e.target.value)}
                          className="w-full bg-red-500/10 border border-red-500/30 rounded-lg p-2 text-red-100 focus:outline-none focus:border-red-500" 
                        />
                      </div>
                      <div>
                        <label className="text-[10px] uppercase tracking-wider text-white/30">Notes</label>
                        <textarea 
