import { GoogleGenAI, Type } from "@google/genai";
import { BlacklistEntry } from "../types";

// --- Image Optimization Configuration ---
// High resolution is critical for reading handwriting and small ID numbers.
const MAX_IMAGE_DIMENSION = 2048; 
const JPEG_QUALITY = 0.90; // Increased quality to ensure handwriting on sticky notes is clear

/**
 * Resizes and compresses an image file before sending to Gemini.
 */
export const fileToGenerativePart = async (file: File): Promise<{ inlineData: { data: string; mimeType: string } }> => {
  return new Promise((resolve, reject) => {
    // If not an image (unlikely given input accept), just pass it through
    if (!file.type.startsWith('image/')) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const base64String = reader.result as string;
        const base64Data = base64String.split(',')[1];
        resolve({ inlineData: { data: base64Data, mimeType: file.type } });
      };
      reader.onerror = reject;
      reader.readAsDataURL(file);
      return;
    }

    const img = new Image();
    const reader = new FileReader();

    reader.onload = (e) => {
      img.src = e.target?.result as string;
    };
    reader.onerror = reject;

    img.onload = () => {
      let width = img.width;
      let height = img.height;

      // Calculate new dimensions while maintaining aspect ratio
      if (width > height) {
        if (width > MAX_IMAGE_DIMENSION) {
          height *= MAX_IMAGE_DIMENSION / width;
          width = MAX_IMAGE_DIMENSION;
        }
      } else {
        if (height > MAX_IMAGE_DIMENSION) {
          width *= MAX_IMAGE_DIMENSION / height;
          height = MAX_IMAGE_DIMENSION;
        }
      }

      const canvas = document.createElement('canvas');
      canvas.width = width;
      canvas.height = height;
      const ctx = canvas.getContext('2d');

      if (!ctx) {
        reject(new Error("Browser does not support canvas context"));
        return;
      }

      // Draw and compress
      ctx.drawImage(img, 0, 0, width, height);

      // Convert to JPEG
      const dataUrl = canvas.toDataURL('image/jpeg', JPEG_QUALITY);

      // Remove prefix "data:image/jpeg;base64,"
      const base64Data = dataUrl.split(',')[1];

      resolve({
        inlineData: {
          data: base64Data,
          mimeType: 'image/jpeg', 
        },
      });
    };

    reader.readAsDataURL(file);
  });
};

export const analyzeDocuments = async (files: File[]): Promise<Partial<BlacklistEntry>[]> => {
  let apiKey: string | undefined;
  try {
    apiKey = process.env.API_KEY;
  } catch (e) {
    console.error("Environment variable access failed:", e);
  }

  if (!apiKey) {
    throw new Error("API Key is missing. Ensure process.env.API_KEY is set in your deployment configuration.");
  }

  const ai = new GoogleGenAI({ apiKey });

  const fileParts = await Promise.all(files.map(fileToGenerativePart));

  const prompt = `
    You are a specialized Data Entry Verification Bot. You are processing images that contain ID Cards and Termination Forms.

    ### CRITICAL FIX: PREVENT NAME MIXING
    **ISSUE**: You have been incorrectly assigning the name of the first applicant to the second applicant because they share a first name (e.g., "Murtada").
    **STRICT INSTRUCTION**: 
    1. Treat every ID card as a completely separate entity. 
    2. Wipe your memory of the "Name" field after processing each card.
    3. **IF THE CARD IS IN ARABIC**: You MUST transliterate the Arabic name printed on *that specific card*. 
       - Example: If the card says "مرتضى صبار مطر", the name is "Murtada Sabbar Matar".
       - Example: If the card says "مرتضى مهدي صالح", the name is "Murtada Mahdi Saleh".
       - **DO NOT** output "Murtada Mahdi Saleh" for "Murtada Sabbar Matar" just because the first name matches.

    ### EXTRACTION PROTOCOL (PER PERSON)

    1. **Identify the ID Card**: Find one plastic ID card.
    2. **Lock Focus**: Look ONLY at this specific card.
    3. **Extract National ID**: Read the 12-digit number from this card.
    4. **Extract Name (VISUAL ANCHOR)**: 
       - Read the name printed **ON THIS SPECIFIC PLASTIC CARD**.
       - If the English name is faded or missing, **READ THE ARABIC NAME** and transliterate it.
       - **FORBIDDEN**: Do NOT use the name from a previous card.

    5. **Find Linked Note**:
       - Now find the Yellow Sticky Note physically attached to the form *underneath* this specific ID card.
       - Extract the 'reasonForBlacklisting' and 'specificNotes' from that sticky note.

    6. **Repeat** for the next ID card/Person.

    ### OUTPUT FORMAT
    Return a JSON Array of objects.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview', // LOCKED IN: Using Gemini 3 Pro Preview
      contents: {
        role: 'user',
        parts: [
          ...fileParts,
          { text: prompt }
        ]
      },
      config: {
        temperature: 0.1, // Low temperature is essential for deterministic OCR
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              nationalId: { type: Type.STRING, description: "12-digit ID from the anchored ID Card" },
              fullName: { type: Type.STRING, description: "Name printed physically on the SAME card as the ID number" },
              passportNumber: { type: Type.STRING },
              department: { type: Type.STRING },
              dateOfHire: { type: Type.STRING },
              dateOfTermination: { type: Type.STRING, description: "YYYY-MM-DD" },
              reasonForBlacklisting: { type: Type.STRING, description: "Violation from the matching sticky note" },
              specificNotes: { type: Type.STRING, description: "Verbatim note content" },
              status: { type: Type.STRING, enum: ["Blacklisted", "Pending Review"] },
            },
            required: ["nationalId", "fullName", "reasonForBlacklisting", "specificNotes"]
          }
        }
      }
    });

    let text = response.text;
    if (!text) throw new Error("AI response was empty.");

    // Clean up potential Markdown code blocks if the model adds them
    text = text.replace(/^```json/, '').replace(/^```/, '').replace(/```$/, '');

    try {
      const data = JSON.parse(text);
      return Array.isArray(data) ? data : [data];
    } catch (parseError) {
      console.error("JSON Parse Error:", parseError, text);
      throw new Error("Failed to parse AI response.");
    }

  } catch (error: any) {
    console.error("Gemini Analysis Error:", error);
    throw new Error(error.message || "Failed to extract data from documents.");
  }
};

